// ===== GLOSSÁRIO =====
const GLOSSARY = [
  {term:"Deontologia", def:"Conjunto de deveres e normas que regem o exercício de uma profissão. Pública e colectiva, distingue-se da ética individual."},
  {term:"Ética", def:"Reflexão filosófica, mais ampla, sobre o bem e o mal e sobre os princípios que devem orientar a conduta humana."},
  {term:"Auto-regulação", def:"Normas e instrumentos criados e adoptados pelos próprios profissionais, sem imposição do Estado (códigos, provedores, livros de estilo)."},
  {term:"Hetero-regulação", def:"Regulação imposta pelo Estado, com legislação e capacidade de aplicar sanções externas (ex.: Lei de Imprensa, ERC)."},
  {term:"Co-regulação", def:"Modelo híbrido que combina regulação estatal e auto-regulação dos profissionais."},
  {term:"M*A*R*S*", def:"Moyens d'Assurer la Responsabilité Sociale des Médias (Bertrand) — instrumentos não estatais de auto-regulação dos media."},
  {term:"M*A*S*", def:"Media Accountability Systems — versão anglófona de M*A*R*S*; sistemas de prestação de contas dos media."},
  {term:"Contrato social", def:"Ideia de que a liberdade de expressão e o acesso à informação vêm acompanhados de responsabilidade social."},
  {term:"Off the record", def:"Informação prestada com a condição de não ser publicada nem atribuída à fonte."},
  {term:"Embargo", def:"Condição segundo a qual a informação só pode ser divulgada a partir de determinado momento."},
  {term:"Sigilo profissional", def:"Dever de proteger a identidade das fontes confidenciais do jornalista."},
  {term:"Presunção de inocência", def:"Princípio segundo o qual não se apresenta como culpada uma pessoa que não foi condenada pelos tribunais."},
  {term:"Cláusula de consciência", def:"Direito do jornalista de recusar práticas que violentem a sua consciência profissional."},
  {term:"Provedor do leitor", def:"Instrumento de auto-regulação que recebe e aprecia queixas do público sobre violações deontológicas."},
  {term:"Livro de estilo", def:"Documento de uma redacção que fixa normas editoriais e linguísticas; instrumento de auto-regulação."},
  {term:"Estatuto de redacção", def:"Instrumento que protege a independência editorial e a participação dos jornalistas nas opções do meio."},
  {term:"Sensacionalismo", def:"Exagero ou dramatização da informação para captar audiência; deve ser combatido segundo o código."},
  {term:"Plágio", def:"Apropriação de trabalho alheio sem atribuição; considerado grave falta profissional."},
  {term:"Relações Públicas", def:"Actividade de comunicação que visa construir e preservar a imagem e a reputação da organização (médio/longo prazo)."},
  {term:"Marketing", def:"Actividade que visa promover produtos/serviços e gerar vendas, com foco no mercado e no consumidor (curto/médio prazo)."},
  {term:"Publicidade", def:"Comunicação comercial paga destinada a informar, persuadir e influenciar (anúncios; foco no curto prazo e ROI)."},
  {term:"Código de Veneza", def:"Código deontológico das RP, criado em 1961 pela Associação Internacional de Relações Públicas."},
  {term:"Código de Atenas", def:"Código deontológico das RP, criado em 1965 pelo Centro Europeu de Relações Públicas (CERP)."},
  {term:"APECOM", def:"Associação Portuguesa das Empresas de Conselho em Comunicação e Relações Públicas."},
  {term:"APCE", def:"Associação (de gestores de) Comunicação de Empresa — define valores como confidencialidade e defesa da livre circulação de informação."},
  {term:"APPM", def:"Associação Portuguesa dos Profissionais de Marketing — código com licitude, honestidade, integridade, responsabilidade social, competência e privacidade."},
  {term:"AMD", def:"Associação de Marketing Digital — código mais recente, abrange IA, redes sociais, influenciadores e e-commerce; tem Comissão de Ética."},
  {term:"Influencer", def:"Pessoa/personagem digital com potencial de influenciar os outros, independentemente do nº de seguidores."},
  {term:"Trabalho emocional", def:"(Hochschild) Mercantilização da personalidade, vida e gostos para construir marca própria e intimidade com o público."},
  {term:"Trabalho relacional", def:"(Baym) Construção e gestão de relações de intimidade entre o influencer e a sua audiência."},
  {term:"Guia de Boas Práticas (2019)", def:"Documento que orienta a actividade dos influenciadores, exigindo identificação de publicidade e veracidade."},
  {term:"RSO", def:"Responsabilidade Social Organizacional — adopção de padrões e práticas éticas na gestão de negócios."},
  {term:"Stakeholders", def:"Todas as partes interessadas/afectadas pela actividade de uma organização (clientes, trabalhadores, comunidade, investidores...)."},
  {term:"Cidadania organizacional", def:"Capacidade de a organização responder a direitos e deveres que a tornam legítima perante a sociedade."},
  {term:"Sustentabilidade", def:"Responder às necessidades do presente sem comprometer a capacidade das gerações futuras."},
  {term:"Alinhamento ético", def:"(Schlegelmilch & Pollach) Compatibilização entre estratégia ética e os sistemas, estrutura e cultura da organização."},
  {term:"Ética discursiva", def:"(Habermas) Validação de normas através do discurso entre participantes competentes (verdade, retidão, sinceridade)."},
  {term:"Comunicação estratégica", def:"Campanhas planeadas, persuasivas e informativas que auxiliam o cumprimento da missão e respeitam a decisão informada dos stakeholders."},
  {term:"ERC", def:"Entidade Reguladora para a Comunicação Social — regulador estatal dos media em Portugal."},
  {term:"ICAP / Auto Regulação Publicitária", def:"Organismo de auto-regulação da publicidade em Portugal."},
  {term:"Interesse público", def:"Critério que pode justificar o 'mal' causado pelo jornalismo (ex.: denúncia de corrupção)."},
];

